package io.knowledgebrain.collaboration;
import java.util.*;import java.time.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_COLLABORATION_DATABASE_URL",matches=".+")
class GroupReviewQueueIntegrationTest {
 SubmissionFeedbackStoreIntegrationTest f;GroupReviewQueueStore store;FeedbackRetractionStore markers;
 @BeforeEach void setup(){f=new SubmissionFeedbackStoreIntegrationTest();f.setup();store=new GroupReviewQueueStore(f.f.f.source,new GroupStore(f.f.f.source,Clock.systemUTC()));markers=new FeedbackRetractionStore(f.f.f.source,f.f.parent.store,f.f.store,Clock.systemUTC());}
 GroupReviewQueueStore.Page list(String filter,UUID after,int limit){return store.list(f.f.group,f.f.space,after,limit,filter);}
 GroupReviewQueueStore.Row row(){return list("ALL",null,100).items().stream().filter(v->v.submissionId().equals(f.answer.submissionId())).findFirst().orElseThrow();}
 FeedbackRetractionStore.Retraction mark(long target,long expected,String state){return markers.change(f.f.group,f.f.space,f.f.study,f.f.assignment,f.answer.submissionId(),f.f.f.owner,target,expected,new FeedbackRetractionInput(state,"PRIVATE marker reason"),f.f.f.trace);}
 UUID task(){var id=f.f.parent.create(f.f.f.key()).assignment().assignmentId();f.f.parent.store.state(f.f.group,f.f.space,f.f.study,id,f.f.f.owner,1,"OPEN",f.f.f.trace);return id;}
 @Test void defaultMissingMetadataAndOwnerOwnReviewAreContentFreeAndReadOnly(){
  int events=f.f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class);assertEquals("MISSING",row().feedbackStatus());assertTrue(row().needsFeedback());assertNull(row().feedbackVersion());assertNull(row().retractionVersion());assertEquals("NONE",row().requestState());assertNull(row().requestVersion());assertEquals(1,list("NEEDS_FEEDBACK",null,20).items().size());assertTrue(list("HAS_FEEDBACK",null,20).items().isEmpty());assertEquals(events,f.f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class));
  var self=f.f.store.submit(f.f.group,f.f.space,f.f.study,f.f.assignment,f.f.f.owner,0,2,f.f.f.key(),"PRIVATE OWNER ANSWER",f.f.f.trace).submission();assertEquals(2,list("ALL",null,20).items().size());assertTrue(list("ALL",null,20).items().stream().anyMatch(v->v.submissionId().equals(self.submissionId())));assertEquals(1,new StudyGradingQueueStore(f.f.f.source,f.f.parent.parent.store).list(f.f.group,f.f.space,f.f.study,f.f.f.owner,null,20,"ALL").items().size());f.store.change(f.f.group,f.f.space,f.f.study,f.f.assignment,self.submissionId(),f.f.f.owner,0,new SubmissionFeedbackInput("PRIVATE OWNER COMMENT",1,2),f.f.f.trace);assertEquals(1,list("HAS_FEEDBACK",null,20).items().size());var json=tools.jackson.databind.json.JsonMapper.builder().build().valueToTree(row());assertEquals(20,json.size());for(String key:List.of("content","reason","score","reviewerId","feedbackId","requestId","snapshot"))assertFalse(json.has(key));
 }
 @Test void resubmissionKeepsPriorOpinionAndRetractedFilterIncludesOldAnswer(){
  f.change(0,1,"Original feedback");assertEquals("CURRENT",row().feedbackStatus());f.f.submit(f.f.f.key(),1,2,"New answer");assertEquals("OUTDATED",row().feedbackStatus());assertEquals(1L,row().feedbackSubmissionVersion());mark(1,0,"RETRACTED");assertEquals("OUTDATED",row().feedbackStatus());assertEquals("RETRACTED",row().retractionState());assertEquals(1,list("NEEDS_FEEDBACK",null,20).items().size());assertEquals(1,list("RETRACTED_FEEDBACK",null,20).items().size());assertTrue(list("HAS_FEEDBACK",null,20).items().isEmpty());f.change(1,2,"Original feedback");assertEquals("CURRENT",row().feedbackStatus());assertEquals(2L,row().feedbackVersion());assertEquals(2L,row().feedbackSubmissionVersion());assertEquals("NONE",row().retractionState());assertTrue(list("RETRACTED_FEEDBACK",null,20).items().isEmpty());
 }
 @Test void latestFeedbackVersionAloneDeterminesCurrentMarkerAndRestoration(){
  f.change(0,1,"First");mark(1,0,"RETRACTED");assertEquals("RETRACTED",row().feedbackStatus());mark(1,1,"RESTORED");assertEquals("CURRENT",row().feedbackStatus());assertEquals("RESTORED",row().retractionState());f.change(1,1,"New text");mark(1,2,"RETRACTED");assertEquals("CURRENT",row().feedbackStatus());assertEquals("NONE",row().retractionState());assertNull(row().retractionVersion());mark(2,0,"RETRACTED");assertEquals("RETRACTED",row().feedbackStatus());assertEquals(1,list("RETRACTED_FEEDBACK",null,20).items().size());mark(2,1,"RESTORED");assertEquals("CURRENT",row().feedbackStatus());assertEquals(2L,row().retractionVersion());
 }
 @Test void unknownMarkerFailsClosedInsteadOfEndorsingCurrentOpinion(){
  f.change(0,1,"PRIVATE feedback");var marker=mark(1,0,"RETRACTED");String saved=f.f.f.jdbc.queryForObject("SELECT snapshot::text FROM feedback_retraction WHERE retraction_id=?",String.class,marker.retractionId());try{for(String expression:List.of("snapshot-'state'","jsonb_set(snapshot,'{state}','\"INVALID\"')")){f.f.f.jdbc.update("UPDATE feedback_retraction SET snapshot="+expression+" WHERE retraction_id=?",marker.retractionId());assertEquals("UNAVAILABLE",row().feedbackStatus());assertEquals("UNKNOWN",row().retractionState());assertTrue(list("HAS_FEEDBACK",null,20).items().isEmpty());assertTrue(list("RETRACTED_FEEDBACK",null,20).items().isEmpty());assertEquals(1,list("UNAVAILABLE",null,20).items().size());}}finally{f.f.f.jdbc.update("UPDATE feedback_retraction SET snapshot=?::jsonb WHERE retraction_id=?",saved,marker.retractionId());}
 }
 @Test void keysetFiltersBeforeLimitAcrossOwnAssignments(){
  f.change(0,1,"First");for(int n=0;n<10;n++){UUID assignment=task();var sub=f.f.store.submit(f.f.group,f.f.space,f.f.study,assignment,f.f.author,0,2,f.f.f.key(),"ANSWER",f.f.f.trace).submission();f.store.change(f.f.group,f.f.space,f.f.study,assignment,sub.submissionId(),f.f.f.owner,0,new SubmissionFeedbackInput("COMMENT",1,2),f.f.f.trace);if(n%2==0)f.f.store.submit(f.f.group,f.f.space,f.f.study,assignment,f.f.author,1,2,f.f.f.key(),"NEW ANSWER",f.f.f.trace);}
  assertEquals(11,list("ALL",null,100).items().size());assertEquals(6,list("HAS_FEEDBACK",null,100).items().size());assertEquals(5,list("NEEDS_FEEDBACK",null,100).items().size());var seen=new ArrayList<UUID>();UUID after=null;do{var p=list("HAS_FEEDBACK",after,2);seen.addAll(p.items().stream().map(GroupReviewQueueStore.Row::submissionId).toList());after=p.nextAfter();}while(after!=null);assertEquals(list("HAS_FEEDBACK",null,100).items().stream().map(GroupReviewQueueStore.Row::submissionId).toList(),seen);assertEquals(6,new HashSet<>(seen).size());
 }
 @Test void currentLabelsOriginalVersionsAndExactGroupPendingEmptyBounds(){
  f.change(0,1,"Original");f.f.parent.store.metadata(f.f.group,f.f.space,f.f.study,f.f.assignment,f.f.f.owner,2,"Current task <script>","Changed instructions",f.f.f.trace);assertEquals("Current task <script>",row().assignmentTitle());assertEquals(2,row().assignmentVersion());assertEquals(2,f.get(f.f.author,false).feedback().assignmentVersion());f.status(404,()->store.list(f.f.f.ids.next(),f.f.space,null,20,"ALL"));f.status(404,()->store.list(f.f.group,f.f.f.ids.next(),null,20,"ALL"));var groups=new GroupStore(f.f.f.source,Clock.systemUTC());var pending=groups.request(f.f.f.owner,f.f.f.key(),"Empty Group","",f.f.f.trace);UUID space=f.f.f.ids.next();f.status(404,()->store.list(pending.groupId(),space,null,20,"ALL"));groups.activate(pending.groupId(),f.f.f.owner,space,f.f.f.trace);assertTrue(store.list(pending.groupId(),space,null,20,"ALL").items().isEmpty());for(int limit:List.of(0,101))f.status(400,()->list("ALL",null,limit));for(String filter:List.of("current","CURRENT","MISSING","NEEDS_GRADING","REQUESTED","","CURRENT' OR TRUE--"))f.status(400,()->list(filter,null,20));
 }
 @Test void closedArchivedReadsKeepOriginalOpinionMarkerAndEventsUnchanged(){
  var feedback=f.change(0,1,"Original");var marker=mark(1,0,"RETRACTED");f.f.parent.store.state(f.f.group,f.f.space,f.f.study,f.f.assignment,f.f.f.owner,2,"CLOSED",f.f.f.trace);f.f.parent.store.state(f.f.group,f.f.space,f.f.study,f.f.assignment,f.f.f.owner,3,"RETIRED",f.f.f.trace);f.f.parent.parent.store.state(f.f.group,f.f.space,f.f.study,f.f.f.owner,1,"RETIRED",f.f.f.trace);int events=f.f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class);for(String filter:GroupReviewQueueStore.FILTERS)list(filter,null,20);assertEquals("RETRACTED",row().feedbackStatus());assertEquals(feedback,f.get(f.f.author,false).feedback());assertEquals(marker,markers.get(f.f.group,f.f.space,f.f.study,f.f.assignment,f.answer.submissionId(),f.f.author,false,1).retraction());assertEquals(events,f.f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class));
 }
 @Test void concurrentAnswerAndFeedbackReadsShareOneStatementSnapshot()throws Exception{
  f.change(0,1,"Original");try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var barrier=new CyclicBarrier(2);var reader=pool.submit(()->{barrier.await();for(int n=0;n<30;n++){var v=row();assertTrue(v.feedbackSubmissionVersion()<=v.version());if(v.feedbackStatus().equals("CURRENT"))assertEquals(v.version(),v.feedbackSubmissionVersion());else assertEquals("OUTDATED",v.feedbackStatus());}return true;});var writer=pool.submit(()->{barrier.await();f.f.submit(f.f.f.key(),1,2,"New answer");return f.change(1,2,"New feedback");});assertTrue(reader.get(20,TimeUnit.SECONDS));assertEquals(2,writer.get(20,TimeUnit.SECONDS).version());assertEquals("CURRENT",row().feedbackStatus());}
 }
 UUID task(UUID study){var id=f.f.parent.store.create(f.f.group,f.f.space,study,f.f.f.owner,f.f.f.key(),"Task <script>","Shared",f.f.f.trace).assignment().assignmentId();f.f.parent.store.state(f.f.group,f.f.space,study,id,f.f.f.owner,1,"OPEN",f.f.f.trace);return id;}
 @Test void allStandaloneStudiesUseCurrentLabelsWithoutCourseRequirement(){
  UUID second=task(f.f.study);var answer=f.f.store.submit(f.f.group,f.f.space,f.f.study,second,f.f.author,0,2,f.f.f.key(),"PRIVATE SECOND ANSWER",f.f.f.trace).submission();var outside=f.f.parent.parent.create(f.f.f.key()).study();UUID other=task(outside.studyId());f.f.store.submit(f.f.group,f.f.space,outside.studyId(),other,f.f.author,0,2,f.f.f.key(),"EXCLUDED OTHER STUDY",f.f.f.trace);assertEquals(3,list("ALL",null,100).items().size());assertTrue(list("ALL",null,100).items().stream().anyMatch(v->v.assignmentId().equals(other)&&v.studyId().equals(outside.studyId())));assertEquals(0,f.f.f.jdbc.queryForObject("SELECT count(*) FROM group_course WHERE group_id=?",Integer.class,f.f.group));
  f.f.parent.store.metadata(f.f.group,f.f.space,f.f.study,second,f.f.f.owner,2,"Current task title <script>","New instructions",f.f.f.trace);var row=list("ALL",null,100).items().stream().filter(v->v.submissionId().equals(answer.submissionId())).findFirst().orElseThrow();assertEquals("Current task title <script>",row.assignmentTitle());assertEquals(2,row.assignmentVersion());f.f.parent.parent.store.state(f.f.group,f.f.space,f.f.study,f.f.f.owner,1,"RETIRED",f.f.f.trace);int events=f.f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class);for(String filter:GroupReviewQueueStore.FILTERS)list(filter,null,20);assertEquals("RETIRED",list("ALL",null,20).items().getFirst().studyState());assertEquals(0,f.f.f.jdbc.queryForObject("SELECT count(*) FROM group_course WHERE group_id=?",Integer.class,f.f.group));assertEquals(events,f.f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event",Integer.class));
 }

 @Test void filterKeysetSpansAssignmentsAndAuthorsWithoutUnsubmittedRoster(){
  task();for(int n=0;n<10;n++){UUID study=n%2==0?f.f.study:f.f.parent.parent.create(f.f.f.key()).study().studyId();UUID assignment=task(study);for(int m=0;m<2;m++){var answer=f.f.store.submit(f.f.group,f.f.space,study,assignment,f.f.f.ids.next(),0,2,f.f.f.key(),"PRIVATE ANSWER",f.f.f.trace).submission();if(m==0)f.store.change(f.f.group,f.f.space,study,assignment,answer.submissionId(),f.f.f.owner,0,new SubmissionFeedbackInput("PRIVATE COMMENT",1,2),f.f.f.trace);}}
  assertEquals(21,list("ALL",null,100).items().size());assertEquals(10,list("HAS_FEEDBACK",null,100).items().size());assertEquals(11,list("NEEDS_FEEDBACK",null,100).items().size());var seen=new ArrayList<UUID>();UUID after=null;do{var p=list("HAS_FEEDBACK",after,3);seen.addAll(p.items().stream().map(GroupReviewQueueStore.Row::submissionId).toList());after=p.nextAfter();}while(after!=null);assertEquals(list("HAS_FEEDBACK",null,100).items().stream().map(GroupReviewQueueStore.Row::submissionId).toList(),seen);assertEquals(10,new HashSet<>(seen).size());
 }
 ResubmissionRequestStore requests(){return new ResubmissionRequestStore(f.f.f.source,f.f.parent.store,Clock.systemUTC());}
 ResubmissionRequestStore.Request request(long version,long source){return requests().change(f.f.group,f.f.space,f.f.study,f.f.assignment,f.answer.submissionId(),f.f.f.owner,version,new ResubmissionRequestInput("REQUEST","PRIVATE request reason",source,2),f.f.f.trace);}
 @Test void independentRequestsCancelResolveAndOldSubmissionReplayCannotResolveLaterRequest(){
  f.change(0,1,"CURRENT");request(0,1);assertEquals(1,list("PENDING_RESUBMISSION",null,20).items().size());assertEquals(1,list("HAS_FEEDBACK",null,20).items().size());requests().change(f.f.group,f.f.space,f.f.study,f.f.assignment,f.answer.submissionId(),f.f.f.owner,1,new ResubmissionRequestInput("CANCEL",null,0,0),f.f.f.trace);assertEquals("CANCELLED",row().requestState());f.f.submit(f.f.f.key(),1,2,"After cancellation");assertEquals("CANCELLED",row().requestState());request(2,2);String key=f.f.f.key();f.f.submit(key,2,2,"Resolving answer");assertEquals("RESOLVED",row().requestState());assertEquals(2L,row().requestedSubmissionVersion());assertTrue(list("PENDING_RESUBMISSION",null,20).items().isEmpty());assertEquals("OUTDATED",row().feedbackStatus());request(4,3);assertFalse(f.f.submit(key,2,2,"Resolving answer").applied());assertEquals("REQUESTED",row().requestState());assertEquals(5L,row().requestVersion());assertEquals(3L,row().requestedSubmissionVersion());f.change(1,3,"Fresh current feedback");assertEquals(1,list("HAS_FEEDBACK",null,20).items().size());assertEquals(1,list("PENDING_RESUBMISSION",null,20).items().size());assertTrue(list("NEEDS_FEEDBACK",null,20).items().isEmpty());
 }
 @Test void missingUnknownAndInconsistentRequestStatesNeverCountAsPendingOrResolved(){
  var req=request(0,1);f.f.submit(f.f.f.key(),1,2,"Resolving answer");f.change(0,2,"Known current feedback");String saved=f.f.f.jdbc.queryForObject("SELECT snapshot::text FROM resubmission_request WHERE request_id=?",String.class,req.requestId());try{for(String expression:List.of("snapshot-'state'","jsonb_set(snapshot,'{state}','\"INVALID\"')","jsonb_set(snapshot,'{state}','\"REQUESTED\"')","jsonb_set(snapshot,'{state}','\"CANCELLED\"')")){f.f.f.jdbc.update("UPDATE resubmission_request SET snapshot="+expression+" WHERE request_id=?",req.requestId());assertEquals("UNAVAILABLE",row().requestState());assertEquals("CURRENT",row().feedbackStatus());assertFalse(row().needsFeedback());assertEquals(1,list("UNAVAILABLE",null,20).items().size());assertEquals(1,list("HAS_FEEDBACK",null,20).items().size());assertTrue(list("PENDING_RESUBMISSION",null,20).items().isEmpty());}}finally{f.f.f.jdbc.update("UPDATE resubmission_request SET snapshot=?::jsonb WHERE request_id=?",saved,req.requestId());}
 }
 @Test void concurrentAtomicRequestResolutionAndFeedbackProvenanceShareOneStatementSnapshot()throws Exception{
  request(0,1);f.change(0,1,"Before new answer");try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var barrier=new CyclicBarrier(2);var read=pool.submit(()->{barrier.await();for(int n=0;n<30;n++){var v=row();if(v.requestState().equals("REQUESTED"))assertEquals(v.version(),v.requestedSubmissionVersion());else{assertEquals("RESOLVED",v.requestState());assertTrue(v.requestedSubmissionVersion()<v.version());}if(v.feedbackStatus().equals("CURRENT"))assertEquals(v.version(),v.feedbackSubmissionVersion());else assertEquals("OUTDATED",v.feedbackStatus());assertEquals(!v.feedbackStatus().equals("CURRENT"),v.needsFeedback());}return true;});var write=pool.submit(()->{barrier.await();return f.f.submit(f.f.f.key(),1,2,"New resolving answer");});assertTrue(read.get(20,TimeUnit.SECONDS));assertTrue(write.get(20,TimeUnit.SECONDS).applied());assertEquals("RESOLVED",row().requestState());}
 }
 @Test void foreignGroupSubmissionsNeverEnterCurrentGroupQueue(){
  var groups=new GroupStore(f.f.f.source,Clock.systemUTC());UUID otherSpace=f.f.f.ids.next();var g=groups.request(f.f.f.owner,f.f.f.key(),"Other Group","",f.f.f.trace);groups.activate(g.groupId(),f.f.f.owner,otherSpace,f.f.f.trace);var studies=new StudyStore(f.f.f.source,Clock.systemUTC());UUID study=studies.create(g.groupId(),otherSpace,f.f.f.owner,f.f.f.key(),"Foreign Study","",f.f.f.trace).study().studyId();var assignments=f.f.parent.store;UUID assignment=assignments.create(g.groupId(),otherSpace,study,f.f.f.owner,f.f.f.key(),"Foreign task","",f.f.f.trace).assignment().assignmentId();assignments.state(g.groupId(),otherSpace,study,assignment,f.f.f.owner,1,"OPEN",f.f.f.trace);var foreign=f.f.store.submit(g.groupId(),otherSpace,study,assignment,f.f.author,0,2,f.f.f.key(),"FOREIGN PRIVATE ANSWER",f.f.f.trace).submission();assertEquals(1,list("ALL",null,100).items().size());assertFalse(list("ALL",null,100).items().stream().anyMatch(v->v.submissionId().equals(foreign.submissionId())));assertEquals(foreign.submissionId(),store.list(g.groupId(),otherSpace,null,20,"ALL").items().getFirst().submissionId());
 }
}
